fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping digit char to its good count according to the problem statement
    fn good_count(d: char) -> u32 {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // Since input first two chars are guaranteed to be digits, this will not happen
        }
    }

    // Extract the first two characters (guaranteed to be ASCII decimal digits)
    let first = input[0];
    let second = input[1];

    // Compute the product of their good counts
    let product = good_count(first) * good_count(second);

    // Convert the product to decimal digits (no leading zeros guaranteed by format!)
    let mut output = product.to_string().chars().collect::<Vec<char>>();

    // Append trailing newline character
    output.push('\n');

    output
}